\set ON_ERROR_STOP on
begin;
-- Nurse chat is dark: the existing RPC must still let the assigned nurse
-- advance and complete ordinary coordination work owned by the doctor.
update public.nurse_chat_settings set enabled=false where singleton;
create temp table coordination_fixture as select gen_random_uuid() a,gen_random_uuid() d,gen_random_uuid() n,gen_random_uuid() other,gen_random_uuid() m,gen_random_uuid() m2,gen_random_uuid() c,gen_random_uuid() c2,gen_random_uuid() task,gen_random_uuid() referral,gen_random_uuid() orphan,gen_random_uuid() orphan_cancel,gen_random_uuid() rollback_task,gen_random_uuid() rollback_request,gen_random_uuid() old_session,gen_random_uuid() plan,gen_random_uuid() request,gen_random_uuid() referral_request,gen_random_uuid() sid_a,gen_random_uuid() sid_d,gen_random_uuid() sid_n,gen_random_uuid() sid_other;
grant select on coordination_fixture to authenticated;
insert into auth.users(id,email) select id,id||'@example.invalid' from coordination_fixture cross join lateral unnest(array[a,d,n,other,m,m2]) id;
update auth.users set phone='37499000'||substr(id::text,1,8),phone_confirmed_at=clock_timestamp() where id in(select m from coordination_fixture union all select m2 from coordination_fixture);
update public.profiles set display_name='Fictional coordination member' where id in(select m from coordination_fixture union all select m2 from coordination_fixture);
insert into public.workspace_clinics(id,name) select c,'Coordination clinic' from coordination_fixture union all select c2,'Other coordination clinic' from coordination_fixture;
insert into public.workspace_staff(user_id,role,display_name,clinic_id) select a,'admin','Admin',null from coordination_fixture union all select d,'doctor','Doctor',c from coordination_fixture union all select n,'nurse','Nurse',c from coordination_fixture union all select other,'nurse','Other nurse',c2 from coordination_fixture;
insert into auth.sessions(id,user_id,created_at,updated_at) select sid_a,a,clock_timestamp(),clock_timestamp() from coordination_fixture union all select sid_d,d,clock_timestamp(),clock_timestamp() from coordination_fixture union all select sid_n,n,clock_timestamp(),clock_timestamp() from coordination_fixture union all select sid_other,other,clock_timestamp(),clock_timestamp() from coordination_fixture;
insert into public.patient_clinical_cases(user_id,assigned_doctor_id,assigned_nurse_id,draft,draft_evidence_token) select m,d,n,'{"instructions":"Private stable clinical draft"}'::jsonb,'unchanged' from coordination_fixture union all select m2,d,null,null,null from coordination_fixture;
insert into public.patient_care_plans(id,user_id,clinician,instructions) select plan,m,'Existing assigned doctor','Existing published instructions' from coordination_fixture;
insert into public.patient_clinical_publications(user_id,plan_id,request_id,actor_id,case_revision,evidence_token,evidence,review,draft) select m,plan,gen_random_uuid(),d,0,'existing-publication-token','{}','{}','{"instructions":"Existing published instructions"}' from coordination_fixture;
create temp table coordination_evidence_baseline as select m,(public.patient_clinical_evidence(m)->>'token') token from coordination_fixture;
create function pg_temp.coordination_login(who text) returns void language plpgsql as $$declare f record;u uuid;s uuid;begin select * into f from coordination_fixture;u:=case who when 'admin' then f.a when 'doctor' then f.d when 'nurse' then f.n else f.other end;s:=case who when 'admin' then f.sid_a when 'doctor' then f.sid_d when 'nurse' then f.sid_n else f.sid_other end;perform set_config('request.jwt.claim.sub',u::text,true);perform set_config('request.jwt.claim.role','authenticated',true);perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated','session_id',s,'amr',jsonb_build_array(jsonb_build_object('method','password')))::text,true);end$$;
select pg_temp.coordination_login('doctor');set local role authenticated;
do $$declare f record;r jsonb;begin select * into f from coordination_fixture;
 r:=public.patient_coordination_command(f.m,f.task,0,f.request,'create',jsonb_build_object('kind','contact-followup','title','Collect contact','instructions','Operational details only','dueAt',null,'ownerId',f.d));
 if r->>'revision'<>'1' then raise exception 'TEST create revision';end if;
 if public.patient_coordination_command(f.m,f.task,0,f.request,'create',jsonb_build_object('kind','contact-followup','title','Collect contact','instructions','Operational details only','dueAt',null,'ownerId',f.d)) is distinct from r then raise exception 'TEST exact create replay';end if;
 begin perform public.patient_coordination_command(f.m,f.task,0,f.request,'create',jsonb_build_object('kind','contact-followup','title','Changed','instructions','Operational details only','dueAt',null,'ownerId',f.d));raise exception 'TEST changed request allowed';exception when serialization_failure then null;end;
 begin perform public.patient_coordination_command(f.m,gen_random_uuid(),0,gen_random_uuid(),'create',jsonb_build_object('kind','contact-followup','title','Other owner','instructions','Details','dueAt',null,'ownerId',f.other));raise exception 'TEST cross clinic owner';exception when insufficient_privilege then null;end;
 perform public.patient_coordination_command(f.m,f.orphan_cancel,0,gen_random_uuid(),'create',jsonb_build_object('kind','booking-coordination','title','Obsolete orphan task','instructions','Operational work no longer needed','dueAt',null,'ownerId',f.n));
 perform public.patient_coordination_command(f.m,f.orphan,0,gen_random_uuid(),'create',jsonb_build_object('kind','evidence-collection','title','Owner repair task','instructions','Collect operational evidence','dueAt',null,'ownerId',f.n));
 perform public.patient_coordination_command(f.m,f.rollback_task,0,gen_random_uuid(),'create',jsonb_build_object('kind','doctor-referral','title','Rollback task','instructions','Rollback fixture','dueAt',null,'ownerId',f.d));
 perform public.patient_coordination_command(f.m,f.referral,0,gen_random_uuid(),'create',jsonb_build_object('kind','doctor-referral','title','Clinical question referral','instructions','Ask the assigned doctor to review the recorded question','dueAt',null,'ownerId',f.d));
 begin insert into public.patient_coordination_tasks(id,patient_case_id,kind,title,instructions,creator_id,owner_id) values(gen_random_uuid(),f.m,'contact-followup','Direct','Direct',f.d,f.d);raise exception 'TEST direct task insert';exception when insufficient_privilege then null;end;
 begin perform public._patient_coordination_owner_valid(f.m,f.d,false);raise exception 'TEST private helper execute';exception when insufficient_privilege then null;end;
end$$;
reset role;select pg_temp.coordination_login('nurse');set local role authenticated;
do $$declare f record;r jsonb;begin select * into f from coordination_fixture;
 if (select count(*) from public.patient_coordination_tasks)<>5 then raise exception 'TEST assigned RLS task read';end if;
 if public.patient_coordination_snapshot(f.task)->>'ownerId'<>f.d::text then raise exception 'TEST doctor-owned flag-off fixture';end if;
 begin perform public.patient_coordination_command(f.m,gen_random_uuid(),0,gen_random_uuid(),'create',jsonb_build_object('kind','contact-followup','title','Nurse created','instructions','Details','ownerId',f.n));raise exception 'TEST nurse create';exception when insufficient_privilege then null;end;
 perform public.patient_coordination_command(f.m,f.task,1,gen_random_uuid(),'contact','{"outcome":"reached","note":"Fictional contact outcome"}');
 perform public.patient_coordination_command(f.m,f.task,2,gen_random_uuid(),'await-member','{}');
 perform public.patient_coordination_command(f.m,f.task,3,gen_random_uuid(),'reopen','{}');
 perform public.patient_coordination_command(f.m,f.task,4,gen_random_uuid(),'complete','{"note":"Operational follow-up collected"}');
 begin perform public.patient_coordination_command(f.m,f.task,5,gen_random_uuid(),'reopen','{}');raise exception 'TEST terminal reopen';exception when check_violation then null;end;
 begin perform public.patient_coordination_command(f.m,f.referral,1,gen_random_uuid(),'complete','{"note":"Bypass clinical referral"}');raise exception 'TEST referral bypass';exception when check_violation then null;end;
 r:=public.patient_coordination_command(f.m,f.referral,1,f.referral_request,'refer','{"note":"Fictional question recorded for doctor follow-up"}');
 if r->>'status'<>'awaiting-doctor' then raise exception 'TEST referral state';end if;
 perform public.patient_coordination_command(f.m,f.referral,1,f.referral_request,'refer','{"note":"Fictional question recorded for doctor follow-up"}');
 begin perform public.patient_coordination_command(f.m,f.referral,2,gen_random_uuid(),'resolve','{"note":"Nurse resolution"}');raise exception 'TEST nurse resolve';exception when insufficient_privilege then null;end;
 begin perform public.patient_coordination_command(f.m,f.referral,2,gen_random_uuid(),'cancel','{"note":"Nurse did not create this"}');raise exception 'TEST nurse cancel';exception when insufficient_privilege then null;end;
end$$;
reset role;select pg_temp.coordination_login('admin');set local role authenticated;
do $$declare f record;begin select * into f from coordination_fixture;
 begin perform public.patient_coordination_command(f.m,f.referral,2,gen_random_uuid(),'resolve','{"note":"Admin resolution"}');raise exception 'TEST admin resolve';exception when insufficient_privilege then null;end;
 begin perform public.patient_coordination_command(f.m,f.referral,2,gen_random_uuid(),'refer','{"note":"Admin clinical care note"}');raise exception 'TEST admin care note';exception when insufficient_privilege then null;end;
 begin perform public.patient_coordination_command(f.m,f.referral,2,gen_random_uuid(),'cancel','{"note":" "}');raise exception 'TEST empty cancel reason';exception when check_violation then null;end;
end$$;
reset role;select pg_temp.coordination_login('other');set local role authenticated;
do $$declare f record;begin select * into f from coordination_fixture;
 if (select count(*) from public.patient_coordination_tasks)<>0 or (select count(*) from public.patient_coordination_events)<>0 then raise exception 'TEST cross clinic RLS';end if;
 begin perform public.patient_coordination_snapshot(f.referral);raise exception 'TEST unrelated snapshot';exception when insufficient_privilege then null;end;
end$$;
reset role;
-- Referral note and task/event writes roll back together on an injected failure.
create function pg_temp.reject_referral() returns trigger language plpgsql as $$begin if new.note='Injected rollback fixture' then raise check_violation using message='Injected task event failure';end if;return new;end$$;
create trigger coordination_rollback before insert on public.patient_coordination_events for each row execute function pg_temp.reject_referral();
select pg_temp.coordination_login('nurse');set local role authenticated;
do $$declare f record;begin select * into f from coordination_fixture;begin perform public.patient_coordination_command(f.m,f.rollback_task,1,f.rollback_request,'refer','{"note":"Injected rollback fixture"}');raise exception 'TEST injected referral did not fail';exception when check_violation then null;end;end$$;
reset role;
do $$declare f record;begin select * into f from coordination_fixture;if (select revision from public.patient_coordination_tasks where id=f.rollback_task)<>1 or exists(select 1 from public.staff_care_notes where detail->>'coordinationTaskId'=f.rollback_task::text) or exists(select 1 from public.patient_coordination_receipts where request_id=f.rollback_request) then raise exception 'TEST referral rollback fragments';end if;end$$;
drop trigger coordination_rollback on public.patient_coordination_events;
-- Managed nurse pre-acceptance and deleted/inactive boundaries use the same real identity gate.
insert into public.real_staff_invitations(email,display_name,clinic_id,issuer_id,expected_auth_user_id,auth_user_id,role,status,verified_at,accepted_at,accepted_session_id) select n||'@example.invalid','Managed nurse',c,a,n,n,'nurse','accepted',clock_timestamp(),clock_timestamp()-interval '1 minute',sid_n from coordination_fixture;
insert into auth.sessions(id,user_id,created_at,updated_at) select old_session,n,clock_timestamp()-interval '2 hours',clock_timestamp() from coordination_fixture;
select set_config('request.jwt.claim.sub',n::text,true),set_config('request.jwt.claim.role','authenticated',true),set_config('request.jwt.claims',jsonb_build_object('sub',n,'role','authenticated','session_id',old_session,'amr',jsonb_build_array(jsonb_build_object('method','password')))::text,true) from coordination_fixture;
set local role authenticated;
do $$begin if (select count(*) from public.patient_coordination_tasks)<>0 then raise exception 'TEST pre-acceptance nurse task read';end if;end$$;
reset role;
update public.workspace_clinics set active=false where id=(select c from coordination_fixture);
select pg_temp.coordination_login('nurse');set local role authenticated;
do $$begin if (select count(*) from public.patient_coordination_tasks)<>0 then raise exception 'TEST inactive clinic access';end if;end$$;
reset role;
update public.workspace_clinics set active=true where id=(select c from coordination_fixture);
update public.workspace_staff set active=false,removed_at=clock_timestamp() where user_id=(select n from coordination_fixture);
select pg_temp.coordination_login('nurse');set local role authenticated;
do $$begin if (select count(*) from public.patient_coordination_tasks)<>0 then raise exception 'TEST removed nurse access';end if;end$$;
reset role;
update public.workspace_staff set active=true,removed_at=null where user_id=(select n from coordination_fixture);
-- Stale owner stays visible for explicit repair. Current actor can still read.
update public.patient_clinical_cases set assigned_nurse_id=null where user_id=(select m from coordination_fixture);
select pg_temp.coordination_login('nurse');set local role authenticated;
do $$declare f record;begin select * into f from coordination_fixture;
 if (select count(*) from public.patient_coordination_events)<>0 then raise exception 'TEST old owner history';end if;
 begin perform public.patient_coordination_command(f.m,f.referral,1,f.referral_request,'refer','{"note":"Fictional question recorded for doctor follow-up"}');raise exception 'TEST replay after loss of access';exception when insufficient_privilege then null;end;
end$$;
reset role;select pg_temp.coordination_login('admin');set local role authenticated;
do $$declare f record;begin select * into f from coordination_fixture;
 if not (public.patient_coordination_snapshot(f.orphan_cancel)->>'needsReassignment')::boolean then raise exception 'TEST orphan cancellation fixture';end if;
 perform public.patient_coordination_command(f.m,f.orphan_cancel,1,gen_random_uuid(),'cancel','{"note":"Obsolete coordination no longer required"}');
 if public.patient_coordination_snapshot(f.orphan_cancel)->>'status'<>'cancelled' then raise exception 'TEST admin orphan cancellation';end if;
end$$;
reset role;select pg_temp.coordination_login('doctor');set local role authenticated;
do $$declare f record;begin select * into f from coordination_fixture;
 if not (public.patient_coordination_snapshot(f.orphan)->>'needsReassignment')::boolean then raise exception 'TEST stale owner hidden';end if;
 begin perform public.patient_coordination_command(f.m,f.orphan,1,gen_random_uuid(),'contact','{"outcome":"reached","note":"Old owner invalid"}');raise exception 'TEST operation before owner repair';exception when insufficient_privilege then null;end;
 perform public.patient_coordination_command(f.m,f.orphan,1,gen_random_uuid(),'reassign',jsonb_build_object('ownerId',f.d));
 if (public.patient_coordination_snapshot(f.orphan)->>'needsReassignment')::boolean then raise exception 'TEST explicit owner repair';end if;
 perform public.patient_coordination_command(f.m,f.orphan,2,gen_random_uuid(),'cancel','{"note":"No longer required operationally"}');
 perform public.patient_coordination_command(f.m,f.referral,2,gen_random_uuid(),'resolve','{"note":"Operational referral acknowledged by assigned doctor"}');end$$;
reset role;
do $$declare f record;begin select * into f from coordination_fixture;
 if (select count(*) from public.staff_care_notes where patient_case_id=f.m and kind='refer-doctor')<>1 then raise exception 'TEST duplicate referral care note';end if;
 if (select revision from public.patient_clinical_cases where user_id=f.m)<>0 or (select draft_evidence_token from public.patient_clinical_cases where user_id=f.m)<>'unchanged' or (select draft->>'instructions' from public.patient_clinical_cases where user_id=f.m)<>'Private stable clinical draft' then raise exception 'TEST clinical case changed';end if;
 if (select count(*) from public.patient_clinical_publications where user_id=f.m)<>1 or (select draft->>'instructions' from public.patient_clinical_publications where user_id=f.m)<>'Existing published instructions' or (select instructions from public.patient_care_plans where id=f.plan)<>'Existing published instructions' then raise exception 'TEST published care changed';end if;
 if public.patient_clinical_evidence(f.m)->>'token' is distinct from (select token from coordination_evidence_baseline) then raise exception 'TEST computed clinical evidence token changed';end if;
 if (select count(*) from public.patient_clinical_case_events where user_id=f.m)<>0 then raise exception 'TEST fabricated clinical audit';end if;
 if exists(select 1 from public.patient_coordination_tasks t where (select count(*) from public.patient_coordination_events e where e.task_id=t.id)<>t.revision) then raise exception 'TEST task event revision sequence';end if;
end$$;
-- Deleted live session fails even for an unmanaged doctor.
delete from auth.sessions where id=(select sid_d from coordination_fixture);
select pg_temp.coordination_login('doctor');set local role authenticated;
do $$declare f record;begin select * into f from coordination_fixture;if (select count(*) from public.patient_coordination_tasks)<>0 then raise exception 'TEST deleted session task read';end if;begin perform public.patient_coordination_snapshot(f.task);raise exception 'TEST deleted session snapshot';exception when insufficient_privilege then null;end;end$$;
reset role;
rollback;
